const items = $input.all();

if (!items.length || !items[0].json.StudentName) {
  return [{ json: { hasData: false } }];
}

// Group by student
const students = {};
items.forEach(item => {
  const name = item.json.StudentName;
  const date = item.json.Date;
  const status = (item.json.Status || '').toLowerCase();
  if (!name || !date) return;

  if (!students[name]) {
    students[name] = { records: [], byDay: {}, byWeek: {} };
  }

  const d = new Date(date);
  const dayName = ['Sunday','Monday','Tuesday','Wednesday',
                   'Thursday','Friday','Saturday'][d.getDay()];
  const weekNum  = Math.floor(d.getDate() / 7);

  students[name].records.push({ date, status, dayName, weekNum });

  if (!students[name].byDay[dayName]) {
    students[name].byDay[dayName] = { total: 0, absent: 0, late: 0 };
  }
  students[name].byDay[dayName].total++;
  if (status === 'absent') students[name].byDay[dayName].absent++;
  if (status === 'late')   students[name].byDay[dayName].late++;
});

const results = [];

Object.entries(students).forEach(([name, data]) => {
  const records = data.records;
  const total   = records.length;
  if (total < 3) return;

  const absent  = records.filter(r => r.status === 'absent').length;
  const late    = records.filter(r => r.status === 'late').length;
  const present = records.filter(r => r.status === 'present').length;
  const pct     = Math.round(((present + late * 0.5) / total) * 100);

  // Detect day-specific pattern
  const suspiciousDays = [];
  Object.entries(data.byDay).forEach(([day, stats]) => {
    if (stats.total >= 2) {
      const absentRate = Math.round((stats.absent / stats.total) * 100);
      if (absentRate >= 50) {
        suspiciousDays.push(`${day} (absent ${stats.absent}/${stats.total} times)`);
      }
    }
  });

  // Detect consecutive absences
  let maxStreak = 0;
  let currentStreak = 0;
  records.forEach(r => {
    if (r.status === 'absent') {
      currentStreak++;
      maxStreak = Math.max(maxStreak, currentStreak);
    } else {
      currentStreak = 0;
    }
  });

  // Detect recent decline
  const recentRecords = records.slice(-5);
  const recentAbsent  = recentRecords.filter(r => r.status === 'absent').length;
  const decliningTrend = recentAbsent >= 3;

  // Detect late pattern
  const lateRate = Math.round((late / total) * 100);
  const frequentlyLate = lateRate >= 40;

  const patterns = [];
  if (suspiciousDays.length)   patterns.push(`Always absent on: ${suspiciousDays.join(', ')}`);
  if (maxStreak >= 3)          patterns.push(`Consecutive absences: ${maxStreak} days in a row`);
  if (decliningTrend)          patterns.push(`Declining trend: ${recentAbsent} absences in last 5 sessions`);
  if (frequentlyLate)          patterns.push(`Frequently late: ${lateRate}% of sessions`);

  const hasPatterns = patterns.length > 0 || pct < 75;

  results.push({
    hasData:       true,
    hasPatterns:   hasPatterns,
    studentName:   name,
    total:         total,
    present:       present,
    absent:        absent,
    late:          late,
    percentage:    pct,
    maxStreak:     maxStreak,
    decliningTrend: decliningTrend,
    frequentlyLate: frequentlyLate,
    suspiciousDays: suspiciousDays.join(', ') || 'None',
    patterns:      patterns.join(' | ') || 'No specific patterns detected',
    recentPattern: recentRecords.map(r => r.status).join(' → '),
    dayBreakdown:  JSON.stringify(data.byDay)
  });
});

if (!results.length) {
  return [{ json: { hasData: false, message: 'Not enough data to analyse patterns yet.' } }];
}

return results.map(r => ({ json: r }));

const student = $('Loop Over Items').item.json;
const dayBreakdown = JSON.parse(student.dayBreakdown);

const dayLines = Object.entries(dayBreakdown).map(([day, stats]) =>
  `  ${day}: ${stats.absent} absent, ${stats.late} late out of ${stats.total} sessions`
).join('\n');

const prompt = `You are an educational analyst. Based on attendance data, write ONE specific insight about this student's attendance pattern. Be direct and actionable for the tutor.

Student: ${student.studentName}
Overall attendance: ${student.percentage}%
Total sessions: ${student.total} (${student.present} present, ${student.absent} absent, ${student.late} late)
Longest absence streak: ${student.maxStreak} days
Recent pattern (last 5): ${student.recentPattern}
Detected patterns: ${student.patterns}

Attendance by day:
${dayLines}

Write exactly 2 sentences: first sentence describes the pattern, second sentence gives the tutor one specific action to take. No greetings, no sign-offs.`;

return [{
  json: {
    studentName:    student.studentName,
    percentage:     student.percentage,
    patterns:       student.patterns,
    suspiciousDays: student.suspiciousDays,
    maxStreak:      student.maxStreak,
    decliningTrend: student.decliningTrend,
    frequentlyLate: student.frequentlyLate,
    present:        student.present,
    absent:         student.absent,
    late:           student.late,
    total:          student.total,
    recentPattern:  student.recentPattern,
    ollamaBody: JSON.stringify({
      model:  'llama3.2:1b',
      prompt: prompt,
      stream: false
    })
  }
}];

const ollamaData  = $input.all()[0].json;
const studentData = $('Build Pattern Prompt').item.json;
const aiInsight   = (ollamaData.response || 'Analysis unavailable.').trim();

const statusEmoji = studentData.percentage >= 75 ? '🟡' :
                    studentData.percentage >= 60 ? '🟠' : '🔴';

const flags = [];
if (studentData.suspiciousDays !== 'None') flags.push(`📅 Day pattern: ${studentData.suspiciousDays}`);
if (studentData.maxStreak >= 3)            flags.push(`⛓️ Streak: ${studentData.maxStreak} consecutive absences`);
if (studentData.decliningTrend)            flags.push(`📉 Declining trend in recent sessions`);
if (studentData.frequentlyLate)            flags.push(`⏰ Frequently arriving late`);

const message = [
  `${statusEmoji} Attendance Pattern — ${studentData.studentName}`,
  `📊 ${studentData.percentage}% overall (${studentData.present} present | ${studentData.absent} absent | ${studentData.late} late / ${studentData.total} total)`,
  `🔄 Recent: ${studentData.recentPattern}`,
  flags.length ? `\n⚠️ Patterns detected:\n${flags.map(f => `  ${f}`).join('\n')}` : '',
  `\n🤖 ${aiInsight}`,
  '─────────────────────'
].filter(Boolean).join('\n');

return [{ json: { message, studentName: studentData.studentName } }];
